state items: list<{id: number, qty: number}> = [{id: 1, qty: 1}]
handler add(id: number) {
  let i = items.indexOf(items.find(x => x.id == id) ?? {id: -1, qty: 0})
  if i >= 0 { items[i].qty = (items[i].qty ?? 0) + 1 } else { items = items.append({id: id, qty: 1}) }
}

